import{at as e,it as t,n,vt as r}from"./chunks/framework.BFUVyeTq.js";var i=JSON.parse(`{"title":"Real-World Apps","description":"","frontmatter":{},"headers":[],"relativePath":"guide/examples/real-world-apps.md","filePath":"guide/examples/real-world-apps.md"}`),a={name:`guide/examples/real-world-apps.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="real-world-apps" tabindex="-1">Real-World Apps <a class="header-anchor" href="#real-world-apps" aria-label="Permalink to “Real-World Apps”">​</a></h1><p>Perhaps the best place to look for sample code is within real apps! If you know others that aren&#39;t in this list, feel free <a href="https://github.com/NoelDeMartin/soukai/pulls" target="_blank" rel="noreferrer">to open a PR</a>.</p><h2 id="media-kraken" tabindex="-1">Media Kraken <a class="header-anchor" href="#media-kraken" aria-label="Permalink to “Media Kraken”">​</a></h2><p><a href="https://noeldemartin.github.io/media-kraken/" target="_blank" rel="noreferrer">Media Kraken</a> is a media tracker, and it&#39;s being rewritten using this version of Soukai with <a href="https://aerogel.js.org" target="_blank" rel="noreferrer">Aerogel</a>, a framework built with Soukai at its core.</p><p>The rewrite is still in progress, so you&#39;ll find it in the <a href="https://github.com/NoelDeMartin/media-kraken/tree/aerogel" target="_blank" rel="noreferrer"><code>aerogel</code> branch</a>. If you&#39;re looking for an actual app using the latest features (such as local-first synchronization), this is the codebase for you.</p><h2 id="umai" tabindex="-1">Umai <a class="header-anchor" href="#umai" aria-label="Permalink to “Umai”">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">⚠️ Using a previous version</p><p>Umai hasn&#39;t been migrated to <code>soukai-bis</code> yet, so its codebase uses the previous version of Soukai. Check out the <a href="./../getting-started/upgrade-guide.html">Upgrade Guide</a> to see what has changed.</p></div><p><a href="https://umai.noeldemartin.com/" target="_blank" rel="noreferrer">Umai</a> is a local-first recipes manager built with Aerogel. It&#39;s the most complete app built with the previous version of Soukai, so it&#39;s a good place to look at how a full-featured app is structured.</p><h2 id="focus" tabindex="-1">Focus <a class="header-anchor" href="#focus" aria-label="Permalink to “Focus”">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">⚠️ Using a previous version</p><p>Focus hasn&#39;t been migrated to <code>soukai-bis</code> yet, so its codebase uses the previous version of Soukai. Check out the <a href="./../getting-started/upgrade-guide.html">Upgrade Guide</a> to see what has changed.</p></div><p><a href="https://focus.noeldemartin.com/" target="_blank" rel="noreferrer">Focus</a> is the OG, the first app developed with Soukai. It has since been rewritten using Aerogel as well.</p><h2 id="ramen" tabindex="-1">Ramen <a class="header-anchor" href="#ramen" aria-label="Permalink to “Ramen”">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">⚠️ Using a previous version</p><p>Ramen hasn&#39;t been migrated to <code>soukai-bis</code> yet, so its codebase uses the previous version of Soukai. Check out the <a href="./../getting-started/upgrade-guide.html">Upgrade Guide</a> to see what has changed.</p></div><p><a href="https://ramen.noeldemartin.com/" target="_blank" rel="noreferrer">Ramen</a> is, quite possibly, the simplest app using Soukai out there. It may even be a stretch to call it &quot;a real app&quot;, but it&#39;s the perfect place to look at how the library can be used in a codebase that is built with production in mind.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};